import React, { useId, type CSSProperties } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmIcon } from '../zimmIcon';
import { useZimmTextInputState } from 'app/hooks/useZimmTextInputState';

type ZimmTextInputProps = {
  label: string;
  type?: string;
  name?: string;
  inverse?: boolean;
  disabled?: boolean;
  helperText?: string;
  errorText?: string;
  onChange?: (value: string) => void;
  /** Controlled value — pass with `onChange` to let a parent form own the value. */
  value?: string;
  /** Initial value when uncontrolled. Ignored if `value` is provided. */
  defaultValue?: string;
  /**
   * Opt in to the clear-✕ shown once the field has a value. Defaults to false.
   *
   * Not in the design system: the extracted TextfieldV2 spec defines a `trailing-icon`
   * attribute and no `clearable` attribute, and SFCC-55's AC specifies the Stay in Touch
   * section as "an email input field and submit button" — two controls, not three. The
   * clear was originally added on the belief that Figma's footer glyph was an ✕; Kiera
   * confirmed (2026-08-20) it is the submit chevron, which `trailing` now carries.
   *
   * Kept as opt-in rather than deleted because a clear affordance is reasonable on a text
   * input atom (a search field would want one) — it just should not be the atom's decision
   * to impose. No consumer opts in today, so the footer renders one trailing control and
   * matches Figma.
   */
  clearable?: boolean;
  /**
   * Trailing icon-button slot. This IS in the design system: it maps to the extracted
   * TextfieldV2 spec's `trailing-icon` attribute (f2r/02-design/specs/components/text-input.md,
   * Figma node 40000265:374). ZimmInputAction injects the submit chevron here — Kiera confirmed
   * (2026-08-20) that the trailing glyph on the footer email field is the chevron, not an ✕.
   * Renders after the clear button below, which is a separate, unspecified addition.
   */
  trailing?: React.ReactNode;
  style?: CSSProperties;
};

/**
 * Atom — flush text input with floating label. Mirrors zimm-text-input contract
 * (flush + inverse variant).
 *
 * All styling lives in `zimmTextInput.css.ts`, co-located beside this file. The component owns only the
 * interaction state the theme cannot express: the value, focus, and whether the field is
 * filled — `filled` and `focused` are fed back into the recipe so it can resolve the
 * Figma colour cascade and the floated-label position.
 */
export const ZimmTextInput = ({
  label,
  type = 'text',
  name,
  inverse = false,
  disabled = false,
  helperText,
  errorText,
  onChange,
  value: controlledValue,
  defaultValue,
  clearable = false,
  trailing,
  style,
}: ZimmTextInputProps) => {
  const inputId = useId();
  const helperId = `${inputId}-helper`;
  const errorId = `${inputId}-error`;
  const hasError = !!errorText;

  const { value, focused, inputRef, handleChange, handleClear, setFocused } = useZimmTextInputState({
    onChange,
    value: controlledValue,
    defaultValue,
  });

  const styles = useMultiStyleConfig('ZimmTextInput', {
    inverse,
    disabled,
    hasError,
    focused,
    filled: value.length > 0,
  });

  return (
    <chakra.div __css={styles.root} style={style}>
      <chakra.div __css={styles.row}>
        {/* content — label + input stacked */}
        <chakra.div __css={styles.content}>
          <chakra.label htmlFor={inputId} __css={styles.label}>
            {label}
          </chakra.label>
          <chakra.input
            id={inputId}
            ref={inputRef}
            type={type}
            name={name}
            value={value}
            disabled={disabled}
            autoComplete={type === 'email' ? 'email' : undefined}
            onChange={handleChange}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            aria-invalid={hasError}
            aria-describedby={[helperText && helperId, hasError && errorId].filter(Boolean).join(' ') || undefined}
            __css={styles.input}
          />
        </chakra.div>
        {/* Clear-✕ — opt-in only, see `clearable` above. Renders before {trailing}, so a
            field that opts into both shows clear then trailing icon. */}
        {clearable && !disabled && value.length > 0 && (
          <chakra.button type="button" aria-label="Clear input" onClick={handleClear} __css={styles.clearButton}>
            <ZimmIcon type="close" size="sm" aria-hidden={true} />
          </chakra.button>
        )}
        {trailing}
      </chakra.div>
      {helperText && (
        <chakra.p id={helperId} __css={styles.helper}>
          {helperText}
        </chakra.p>
      )}
      {errorText && (
        <chakra.p id={errorId} role="alert" __css={styles.error}>
          {errorText}
        </chakra.p>
      )}
    </chakra.div>
  );
};
