        <button onClick={() => onSubmit('Jane', 'Smith')}>mock-continue</button>
        <button onClick={onClose}>mock-cancel</button>
      </div>
    ) : null,
}));

// useSubscribeSection's own state machine (idle/unavailable/success/error transitions, modal
// open/close, pending-signup capture) is exhaustively covered by useSubscribeSection.test.ts.
// Mocking it here isolates this suite to ZimmSubscribeSection's own contract: given a state, does
// it render the right branch, and does it correctly wire DOM events into the hook's handlers.
vi.mock('app/hooks/useSubscribeSection', () => ({
