}));

// UiCopyProvider's own fetch/lookup logic is covered by its own test file; mocking useUiCopy
// here isolates this suite to ZimmSubscribeSection's own contract rather than a second copy of
// that coverage. Default matches the no-Provider fallback behaviour real callers see in
// Storybook/production-before-content-exists.
vi.mock('app/hooks/useUiCopy', () => ({
  useUiCopy: vi.fn(),
}));

const mockUseSubscribeSection = vi.mocked(useSubscribeSection);
const mockUseUiCopy = vi.mocked(useUiCopy);

const baseProps = {
  heading: 'Keep in Touch',
  body: 'Sign up to stay up to date.',
  privacyPolicyHref: '/privacy-policy',
};

function mockHook(overrides: Partial<ReturnType<typeof useSubscribeSection>> = {}) {
  mockUseSubscribeSection.mockReturnValue({
    submitState: 'idle',
    modalOpen: false,
    closeModal: vi.fn(),
    handleEmailSubmit: vi.fn(),
    handleModalSubmit: vi.fn(),
    ...overrides,
  });
}

describe('ZimmSubscribeSection', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockHook();
    mockUseUiCopy.mockReturnValue({ t: (_key: string, fallback: string) => fallback, isLoading: false });
  });

  test('idle: renders the email input and Subscribe button, no success/error message', () => {
    render(<ZimmSubscribeSection {...baseProps} />);

    expect(screen.getByRole('textbox', { name: /email/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /subscribe/i })).toBeInTheDocument();
    expect(screen.queryByText(/on the list/i)).not.toBeInTheDocument();
    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
  });

  test('success: renders the success message, not the input', () => {
    mockHook({ submitState: 'success' });
    render(<ZimmSubscribeSection {...baseProps} />);

    expect(screen.getByText(/on the list/i)).toBeInTheDocument();
    expect(screen.queryByRole('textbox', { name: /email/i })).not.toBeInTheDocument();
  });

