import { afterEach, beforeEach, describe, test, expect, vi } from 'vitest';
import { resolveBorderColour, resolveHoverBorderColour, resolveLabelColour, ZimmTextInput } from './zimmTextInput.css';
import type { ZimmTextInputStyleProps } from './zimmTextInput.css';

/**
 * The Figma colour cascade is the part of this recipe that can break without surfacing as a
 * type or build error — a mis-ordered branch renders a plausible-but-wrong border. These
 * assertions moved here from useZimmTextInputState.test.ts when the derivation moved out of
 * the hook and into the theme.
 */

// .claude/rules/testing.md asks for beforeEach setup and vi.clearAllMocks() after each test.
// The resolvers here are pure and this file mocks nothing, so these hooks are a convention
// baseline rather than load-bearing isolation — kept so the file matches the rule as written
// and stays correct if a mock is ever introduced.
let base: ZimmTextInputStyleProps;

beforeEach(() => {
  base = { inverse: false, disabled: false, hasError: false, focused: false, filled: false };
});

afterEach(() => {
  vi.clearAllMocks();
});

describe('ZimmTextInput — border colour precedence', () => {
  test('disabled wins over error and filled', () => {
    expect(resolveBorderColour({ ...base, disabled: true, hasError: true, filled: true })).toBe(
      'var(--zimm-color-border-forms)',
    );
  });

  test('error wins over focus and filled', () => {
    expect(resolveBorderColour({ ...base, hasError: true, filled: true })).toBe('var(--zimm-color-status-error)');
  });

  test('a filled but unfocused field darkens to the focus colour', () => {
    expect(resolveBorderColour({ ...base, filled: true })).toBe('var(--zimm-color-border-focus)');
  });

  // focused is its own branch, sitting between hasError and filled. In the light palette
  // focus and filled resolve to the same colour, so only the empty-and-focused case can
  // distinguish "the focus branch ran" from "it fell through to default".
  test('an empty but focused field takes the focus colour, not the default', () => {
    expect(resolveBorderColour({ ...base, focused: true })).toBe('var(--zimm-color-border-focus)');
  });

  test('an empty, unfocused, valid field uses the default border', () => {
    expect(resolveBorderColour(base)).toBe('var(--zimm-color-border-forms)');
  });

  test('hover keeps the error colour when in error, otherwise darkens', () => {
    expect(resolveHoverBorderColour({ ...base, hasError: true })).toBe('var(--zimm-color-status-error)');
    expect(resolveHoverBorderColour(base)).toBe('var(--zimm-color-border-focus)');
  });

  test('inverse mode uses the inverse palette', () => {
    expect(resolveBorderColour({ ...base, inverse: true })).toBe('var(--zimm-color-text-inverse)');
    expect(resolveBorderColour({ ...base, inverse: true, hasError: true })).toBe('var(--zimm-color-status-error-bg)');
  });
});

describe('ZimmTextInput — label colour', () => {
  test('light mode: subtle once floated, default otherwise', () => {
    expect(resolveLabelColour({ ...base, filled: true })).toBe('var(--zimm-color-text-secondary)');
    expect(resolveLabelColour(base)).toBe('var(--zimm-color-text-default)');
  });

  test('inverse mode: grey once floated, white otherwise', () => {
    expect(resolveLabelColour({ ...base, inverse: true, filled: true })).toBe('var(--zimm-color-text-inverse-grey)');
    expect(resolveLabelColour({ ...base, inverse: true })).toBe('var(--zimm-color-text-inverse)');
  });

  test('disabled uses the subtle colour for the mode', () => {
    expect(resolveLabelColour({ ...base, disabled: true })).toBe('var(--zimm-color-text-secondary)');
    expect(resolveLabelColour({ ...base, disabled: true, inverse: true })).toBe('var(--zimm-color-text-inverse-grey)');
  });
});

