===== overrides/app/hooks/useUiCopy.ts =====
import { createContext, useContext } from 'react';

export type UiCopyContextValue = {
  /**
   * Returns the CMS value for `key`, or `fallback` while the fetch is loading, on fetch
   * error, or when no `uiCopy` entry with that key exists yet.
   */
  t: (key: string, fallback: string) => string;
  isLoading: boolean;
};

/**
 * Populated by UiCopyProvider (overrides/app/components/uiCopyProvider), mounted once in
 * _app-config. Not meant to be consumed directly — call useUiCopy() instead, which supplies
 * the no-Provider fallback.
 */
export const UiCopyContext = createContext<UiCopyContextValue | undefined>(undefined);

const FALLBACK_ONLY: UiCopyContextValue = {
  t: (_key: string, fallback: string) => fallback,
  isLoading: false,
};

/**
 * App-wide UI-copy lookup, backed by Contentful's uiCopy content type — one entry per string,
 * fetched in a single bulk call by UiCopyProvider and shared via context, the same pattern
 * this app already uses for translations (`useIntl`) rather than the per-page container-fetch
 * pattern commerce-sdk-react hooks use. uiCopy is app-wide static content, not page-specific
 * business data, so it's safe to call from any component — including presentational leaves —
 * without threading it through as a prop.
 *
 * Safe to call with no UiCopyProvider mounted above it (Storybook, an isolated unit test):
 * degrades to fallback-only text instead of throwing, so every call site stays functional and
 * testable with zero setup.
 *
 * @returns `t` lookup function plus `isLoading`
 */
export const useUiCopy = (): UiCopyContextValue => useContext(UiCopyContext) ?? FALLBACK_ONLY;
===== overrides/app/components/uiCopyProvider/index.tsx =====
import React, { useCallback, useMemo, type ReactNode } from 'react';
import { useContentfulEntries } from 'app/hooks/useContentful';
import { UiCopyContext } from 'app/hooks/useUiCopy';
import type { UiCopyEntry } from 'app/types/contentful';

type UiCopyProviderProps = {
  children: ReactNode;
};

/**
 * Bulk-fetches every `uiCopy` entry in one Delivery API call (`content_type=uiCopy`) and
 * provides the resulting key→value lookup to every descendant via useUiCopy() — mounted once
 * in _app-config, so creating N entries in Contentful costs one call for the whole app, not N
 * calls from N components each independently fetching the same content.
 *
 * @param props.children the app tree to provide uiCopy lookups to
 */
export const UiCopyProvider = ({ children }: UiCopyProviderProps) => {
  const { data, isLoading } = useContentfulEntries<UiCopyEntry>('uiCopy');

  const copyMap = useMemo(() => {
    const map = new Map<string, string>();
    (data ?? []).forEach((entry) => {
      map.set(entry.fields.key, entry.fields.value);
    });
    return map;
  }, [data]);

  // Fallback-on-failure by design, not just a loading placeholder: unlike structural content
  // (e.g. FooterContainer's footerConfig, which renders nothing rather than substitute
  // placeholder content), losing a button label or a status message to a Contentful outage
  // should never blank a control.
  const t = useCallback((key: string, fallback: string): string => copyMap.get(key) ?? fallback, [copyMap]);

  const value = useMemo(() => ({ t, isLoading }), [t, isLoading]);

  return <UiCopyContext.Provider value={value}>{children}</UiCopyContext.Provider>;
};
