// grow with root font-size (WCAG 1.4.4).
const SIZE_SUBSCRIBE_SLOT = '2.8125rem';

export const ZimmSubscribeSection = {
  parts: ['heading', 'body', 'control', 'success', 'error'],
  baseStyle: {
