import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { ZimmSubscribeSection } from './index';

const meta: Meta<typeof ZimmSubscribeSection> = {
  title: 'Forms/ZimmSubscribeSection',
  component: ZimmSubscribeSection,
  // This organism's recipe hard-codes inverse (light-on-dark) colours with no light variant, so
  // mounted in isolation on Storybook's white canvas its own text is unreadable and axe fails it:
  // the `heading` part (--zimm-color-text-inverse-grey, #969696) came out at 2.95:1 against white,
  // below the 4.5:1 AA floor for 12px/500. That's an artefact of the isolated mount, not a defect
  // — in the footer this sits inside the `container` part, which is the only background in the
  // chain (footer.css.ts:25, --zimm-color-bg-05 / #191919), where the same colour is 5.94:1 and
  // passes. Worse, the `body` and input are --zimm-color-text-inverse (#ffffff), i.e. white on
  // white at 1:1 — invisible, and axe did not even report those. This decorator reproduces the
  // shipped background so the a11y check measures the context the component actually renders in.
  decorators: [
    (Story) => (
      <div style={{ backgroundColor: 'var(--zimm-color-bg-05)', padding: 'var(--zimm-scale-2xl)' }}>
        <Story />
      </div>
    ),
  ],
  // No canvas-background setting here on purpose. A `parameters: {backgrounds: {default: 'dark'}}`
  // used to sit at this spot and was a silent no-op — Storybook 10 reads the selection from
  // `globals.backgrounds.value`, and nothing reads `parameters…default` — which is part of why the
  // a11y failure surfaced. The obvious repair, `globals: {backgrounds: {value: 'dark'}}`, was
  // rejected: Storybook's built-in `dark` is #333 against this decorator's #191919, so it would
  // introduce a second, underived dark that can drift from the token. The decorator is the only
  // surface axe or the eye needs.
  args: {
    heading: 'Keep in touch',
    body: 'Be the first to know about new collections and new arrivals.',
    privacyPolicyHref: '/privacy-policy',
  },
};
export default meta;
type Story = StoryObj<typeof ZimmSubscribeSection>;

export const Default: Story = {};

export const Subscribed: Story = {
  args: { initialSubscribed: true },
};

/**
 * Full email → modal → submit interaction coverage (including the a11y/focus assertions) lives
 * at the footer assembly level — footer/index.stories.tsx's SubscribeSubmit and
 * SubscribeModalOpen — since that's the shipped context and testing.md says prove behaviour
 * once, at the cheapest layer. These stories exist for components.md's per-exported-component
 * requirement and for visual variants when this organism is placed elsewhere.
 */
export const NameCaptureEnabled: Story = {
  name: 'Name capture modal enabled (HPC-035, not shipped)',
  args: { enableNameCapture: true },
};

