===== overrides/app/hooks/useZimmModal.ts =====
import { useCallback, useEffect, useRef, useState } from 'react';

const FOCUSABLE = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';

type UseZimmModalParams = {
  /** Whether the dialog is currently open. */
  isOpen: boolean;
  /** Called when the dialog should close (Escape). */
  onClose: () => void;
};

type UseZimmModalReturn = {
  /** False until after the first client render, so the portal is not created during SSR. */
  mounted: boolean;
  /** Attach to the element that bounds the Tab trap — a <form> for SubscribeModal today, but any
   *  container works. Everything focusable inside it is included in the trap. */
  trapRef: React.RefObject<HTMLElement>;
  /** Attach to the wrapper around the first field — its <input> receives initial focus. */
  firstFocusRef: React.RefObject<HTMLDivElement>;
};

/**
 * Generic dialog mechanics: mount gating, focus save/restore, body-scroll lock, and the
 * Escape/Tab keyboard trap. Renamed from useSubscribeModal — the logic never depended on
 * anything subscribe-specific, only on a trap boundary and a first-focus target, so any modal
 * built on the ZimmModal atom can reuse it.
 *
 * Extracted from SubscribeModal per components.md's extract-to-hook threshold — four effects,
 * three of them with cleanup functions. None of it touches JSX, so the component keeps only its
 * markup and the recipe lookup. Behaviour is unchanged from useSubscribeModal; the effect order
 * and dependency arrays are preserved exactly, because focus restore depends on running after
 * the open-effect's cleanup.
 *
 * @param params isOpen and the close callback
 * @returns the mount flag plus the two refs the dialog markup has to attach
 */
export const useZimmModal = ({ isOpen, onClose }: UseZimmModalParams): UseZimmModalReturn => {
  const [mounted, setMounted] = useState(false);
  const trapRef = useRef<HTMLElement>(null);
  const firstFocusRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<Element | null>(null);

  useEffect(() => {
    setMounted(true);
  }, []);

  // Save the trigger element on open so focus can be restored on close
  useEffect(() => {
    if (isOpen) {
      triggerRef.current = document.activeElement;
      // Defer so the portal has rendered before we try to focus inside it
      const id = setTimeout(() => {
        const firstInput = firstFocusRef.current?.querySelector<HTMLElement>('input');
        firstInput?.focus();
      }, 0);
      return () => clearTimeout(id);
    } else {
      // Return focus to the element that opened the modal
      if (triggerRef.current instanceof HTMLElement) {
        triggerRef.current.focus();
      }
    }
  }, [isOpen]);

  // Lock body scroll while modal is open
  useEffect(() => {
    if (!isOpen) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, [isOpen]);

  // Keyboard: Escape to close, Tab trap within the modal
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
        return;
      }
      if (e.key !== 'Tab' || !trapRef.current) return;

      const focusable = Array.from(trapRef.current.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
        (el) => !el.hasAttribute('disabled'),
      );
      if (focusable.length === 0) {
        e.preventDefault();
        return;
      }

      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const active = document.activeElement;

      // Focus can end up outside the trap boundary entirely — e.g. a click on the backdrop
      // before it closes. The two boundary checks below only redirect Tab *at* an edge; without
      // this branch, Tab from an already-escaped focus point would carry the user out into the
      // page behind the modal (WCAG 2.1.2 — no trap the keyboard cannot get back into).
      if (!(active instanceof Node) || !trapRef.current.contains(active)) {
        e.preventDefault();
        (e.shiftKey ? last : first).focus();
      } else if (e.shiftKey && active === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && active === last) {
        e.preventDefault();
        first.focus();
      }
    },
    [onClose],
  );

  useEffect(() => {
    if (!isOpen) return;
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, handleKeyDown]);

  return { mounted, trapRef, firstFocusRef };
};
===== overrides/app/hooks/useZimmTextInputState.ts =====
import { useRef, useState } from 'react';
import type React from 'react';

type UseZimmTextInputStateParams = {
  onChange?: (value: string) => void;
  /** Controlled value. When provided the caller owns the value and internal state is unused. */
  value?: string;
  /** Seed for the uncontrolled case. Ignored when `value` is provided. */
  defaultValue?: string;
};

type UseZimmTextInputStateReturn = {
  value: string;
  focused: boolean;
  inputRef: React.RefObject<HTMLInputElement>;
  handleChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  handleClear: () => void;
  setFocused: React.Dispatch<React.SetStateAction<boolean>>;
};

/**
 * Manages the interaction state for ZimmTextInput that the theme cannot express: the value,
 * and focus. The floated-label decision is NOT made here — the label colour and the border
 * and label colour cascades live in `zimmTextInput.css.ts` (co-located beside the component),
 * which receives `focused` and `filled` as recipe props. Hover is a CSS pseudo-class in that
 * recipe, so it costs no React state.
 *
 * Supports both modes, following the React convention: pass `value` to control it from a
 * parent (a form, or ZimmInputAction), or omit it and the hook owns the value internally,
 * seeded from `defaultValue`. `onChange` fires in both modes.
 * @returns value, focus flag, the input ref, and the event handlers
 */
export const useZimmTextInputState = ({
  onChange,
  value: controlledValue,
  defaultValue,
}: UseZimmTextInputStateParams): UseZimmTextInputStateReturn => {
  // Controlled when the caller passes `value`; otherwise the hook owns it, seeded from
  // `defaultValue`. Reading through this indirection is what makes the returned `value`
  // correct in both modes — and the recipe derives the floated-label state from it.
  const isControlled = controlledValue !== undefined;
  const [internalValue, setInternalValue] = useState(defaultValue ?? '');
  const value = isControlled ? controlledValue : internalValue;
  const [focused, setFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!isControlled) setInternalValue(e.target.value);
    onChange?.(e.target.value);
  };

  const handleClear = () => {
    if (!isControlled) setInternalValue('');
    onChange?.('');
    inputRef.current?.focus();
  };

  return { value, focused, inputRef, handleChange, handleClear, setFocused };
};
===== overrides/app/utils/safeHref.ts =====
/**
 * Allow-list guard for hrefs that originate outside the codebase.
 *
 * Anything reaching an `href` from Contentful, a URL parameter, or a prop supplied by a
 * caller we do not control has to pass through here first. `javascript:` and `data:` URLs
 * execute; an authority reference like `//host` silently leaves the site. The `(?![/\\])`
 * lookahead rejects that, including the backslash form — a browser treats `/\host` as `//host`,
 * so a backslash is an authority reference just as much as a second slash is. `e9c2180` closed
 * only the forward-slash half; the backslash and control-character forms stayed open until now.
 *
 * Allow-list rather than deny-list on purpose: a deny-list has to anticipate every scheme,
 * and browsers keep adding them.
 */
// eslint-disable no-control-regex — the control characters ARE the subject here. The rule exists
// to catch them appearing by accident; these are deliberate, and matching them is the whole point
// of the fix. Suppressed at the point of use rather than in .eslintrc, per the escape-hatch
// convention in .claude/rules/typescript.md.
/* eslint-disable no-control-regex */
const C0_OR_SPACE = /^[\u0000-\u0020]+|[\u0000-\u0020]+$/g;
const TAB_LF_CR = /[\u0009\u000a\u000d]/g;
/* eslint-enable no-control-regex */

/**
 * Normalise the way the URL parser will, before testing.
 *
 * The WHATWG parser strips leading and trailing C0-or-space, and removes tab/LF/CR from anywhere
 * in the input, BEFORE it parses. `/\u0009/evil.com` is therefore parsed as `//evil.com`. Testing
 * the raw string means the allow-list checks a different value than the browser resolves — which
 * is exactly how the earlier fix passed its own tests while leaving the hole open.
 *
 * A plain space is deliberately not stripped: the parser percent-encodes it rather than removing
 * it, so `/ /evil.com` resolves on-site and must stay allowed.
 */
const normalise = (href: string): string => href.replace(C0_OR_SPACE, '').replace(TAB_LF_CR, '');

const SAFE_HREF_RE = /^(https?:|tel:|mailto:|#|\/(?![/\\]))/i;

/** True when `href` is safe to render on an anchor. Absent or unsafe values return false. */
export const isSafeHref = (href: string | undefined): boolean => (href ? SAFE_HREF_RE.test(normalise(href)) : false);

