import React from 'react';
import { createPortal } from 'react-dom';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';

const ZIMM_MODAL_RECIPE = 'ZimmModal';

type ZimmModalProps = {
  /** Whether the dialog is open. Nothing renders until this and `mounted` are both true. */
  isOpen: boolean;
  /** From the paired useZimmModal() call — false until the first client render, so the portal
   *  is never created during SSR. */
  mounted: boolean;
  /** Called on backdrop click (and on Escape, via useZimmModal's own keydown listener). */
  onClose: () => void;
  /** Dialog panel max-width. No default — each modal type has its own Figma-specified size, so
   *  a caller-supplied value is safer than a guessed generic default. */
  maxWidth: string;
  /** id of the element that labels the dialog (aria-labelledby). */
  labelledBy: string;
  /** id of the element that describes the dialog (aria-describedby), if one exists. */
  describedBy?: string;
  children: React.ReactNode;
};

/**
 * Generic modal chrome — portal, backdrop, and an accessible dialog panel. Owns none of the
 * content: a caller supplies its own form/fields as children and pairs this with useZimmModal()
 * for focus/scroll/keyboard mechanics. Split out of the footer's original SubscribeModal so any
 * future dialog — not just the subscribe flow — can reuse the same accessible shell.
 *
 * @param props see ZimmModalProps
 */
export const ZimmModal = ({
  isOpen,
  mounted,
  onClose,
  maxWidth,
  labelledBy,
  describedBy,
  children,
}: ZimmModalProps) => {
  const styles = useMultiStyleConfig(ZIMM_MODAL_RECIPE, {});

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) onClose();
  };

  if (!mounted || !isOpen) return null;

  return createPortal(
    <chakra.div role="presentation" onClick={handleBackdropClick} __css={styles.overlay}>
      <chakra.div
        role="dialog"
        aria-modal="true"
        aria-labelledby={labelledBy}
        aria-describedby={describedBy}
        __css={{ ...styles.panel, maxWidth }}
      >
        {children}
      </chakra.div>
    </chakra.div>,
    document.body,
  );
};
=== zimmModal.css.ts ===
// Generic dialog chrome — overlay + panel + actions row. Component-specific content styling
// (title, fields, consent copy, etc.) belongs in the consuming organism's own recipe, not here —
// see e.g. zimmSubscribeModal.css.ts. Split out of the footer's original combined recipe so a
// future non-subscribe modal has somewhere to register its own chrome and content separately.
export const ZimmModal = {
  parts: ['overlay', 'panel', 'actions'],
  baseStyle: {
    // Rendered through a portal, so it escapes any caller's stacking context.
    overlay: {
      position: 'fixed',
      inset: 0,
      // brand dark overlay (grey-900 base), not pure black
      background: 'var(--zimm-color-opacity-50)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 'var(--zimm-scale-l)',
      // Chakra zIndices.overlay (1300). Must clear the sticky header, which sets
      // zIndex: 'sticky' (1100) in header.ts. The portal target is document.body, so this
      // competes in the root stacking context, not the caller's.
      zIndex: 'overlay',
    },
    // Light surface — every current use case contrasts against a dark parent (the footer).
    // maxWidth is deliberately NOT set here — ZimmModal takes it as a required prop, since each
    // dialog type has its own Figma-specified size.
    panel: {
      backgroundColor: 'var(--zimm-color-bg-07)',
      width: '100%',
      padding: 'var(--zimm-scale-3xl)',
    },
    actions: { display: 'flex', gap: 'var(--zimm-scale-m)', justifyContent: 'flex-end' },
  },
};

